// ---------------------------------------------------------------------------
// COMBINED REGISTRY — Single export for all known tokens
// ---------------------------------------------------------------------------

export const ATROPA_TOKEN_REGISTRY: AtropaTokenEntry[] = [
    ...CORE_TOKENS,
    ...CORE_ECONOMY_TOKENS,
    ...V1_TOKENS,
    ...V2_TOKENS,
    ...V3_TOKENS,
    ...V4_TOKENS,
];

// Helper: get tokens by minter type
export function getRegistryTokensByMinter(minterType: MinterType): AtropaTokenEntry[] {
    return ATROPA_TOKEN_REGISTRY.filter(t => t.minterType === minterType);
}

// Helper: get CORE tokens by sub-category
export function getCoreTokensBySubCategory(sub: CoreSubCategory): AtropaTokenEntry[] {
    return ATROPA_TOKEN_REGISTRY.filter(
        t => t.minterType === 'CORE' && t.coreSubCategory === sub
    );
}

// Helper: check if an address is in the registry
export function isInRegistry(address: string): AtropaTokenEntry | undefined {
    const lower = address.toLowerCase();
    return ATROPA_TOKEN_REGISTRY.find(t => t.address.toLowerCase() === lower);
}
